# Patterns for strings that carry a car or photographer name: (English regex, {lang: replacement}).
PATTERNS = [
    (r'^(.+) photo$', {'pt': r'Fotografia: \1', 'es': r'Foto: \1', 'fr': 'Photo : \\1', 'de': r'Foto: \1', 'he': r'תמונה: \1'}),
    (r'^by (.+),$', {'pt': r'de \1,', 'es': r'de \1,', 'fr': r'par \1,', 'de': r'von \1,', 'he': r'מאת \1,'}),
    (r'^(.+) · reference photograph$', {'pt': r'\1 · fotografia de referência', 'es': r'\1 · foto de referencia', 'fr': r'\1 · photo de référence', 'de': r'\1 · Referenzfoto', 'he': r'\1 · תמונת ייחוס'}),
    (r'^(.+) · catalogue photograph$', {'pt': r'\1 · fotografia do catálogo', 'es': r'\1 · foto del catálogo', 'fr': r'\1 · photo du catalogue', 'de': r'\1 · Katalogfoto', 'he': r'\1 · תמונה מהקטלוג'}),
]
